/**
 * Copy buttons for the credentials page when the Material theme is not the active theme.
 *
 * @module     local_materialtools/copy
 * @copyright  2026 Ding Ding Projects
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define('local_materialtools/copy', [], function() {
    return {
        /**
         * Handle [data-md-copy] buttons unless the Material theme already does.
         */
        init: function() {
            if (document.documentElement.hasAttribute('data-md-motion')) {
                return;
            }
            document.addEventListener('click', function(e) {
                var button = e.target.closest ? e.target.closest('[data-md-copy]') : null;
                if (!button) {
                    return;
                }
                var node = document.getElementById(button.getAttribute('data-md-copy'));
                var text = node ? (node.tagName === 'TEXTAREA' ? node.value : node.textContent) : '';
                var original = button.textContent;
                var done = function() {
                    button.textContent = button.getAttribute('data-md-copied-label') || '✓';
                    setTimeout(function() {
                        button.textContent = original;
                    }, 1500);
                };
                if (navigator.clipboard && window.isSecureContext) {
                    navigator.clipboard.writeText(text).then(done).catch(function() {
                        return null;
                    });
                } else if (node && node.select) {
                    node.select();
                    document.execCommand('copy');
                    done();
                }
            });
        }
    };
});
